### cot
Step 1. Verify that the script path points to an existing file; if not, raise FileNotFoundError.
Step 2. Launch the script as a subprocess using the Python interpreter.
Step 3. Start a worker thread that waits for the subprocess to complete to avoid blocking the main thread.
Step 4. Wait for the thread with the specified timeout. If the thread is still alive after the timeout, terminate the subprocess, wait briefly, and force-kill if needed.
Step 5. If the process was terminated due to timeout, return "Terminating process due to timeout.". Otherwise, return "Script executed successfully."

### code
```
import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError("Script file does not exist")
    process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    def run():
        try:
            process.communicate()
        except Exception:
            pass
    t = threading.Thread(target=run)
    t.start()
    t.join(timeout)
    if t.is_alive():
        try:
            process.terminate()
        except Exception:
            pass
        try:
            process.wait(timeout=5)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
        t.join()
        return "Terminating process due to timeout."
    return "Script executed successfully."
